def has_dup(xs):
    seen = set()
    for x in xs:
        if x in seen:
            return True
        seen.add(x)
    return False

def pairs(xs):
    n = len(xs)
    c = 0
    for i in range(n):
        for j in range(i, n):
            c += 1
    return c

def common(xs, ys):
    out = []
    for x in xs:
        if x in ys:      # ys is a list
            out.append(x)
    return out

def f(n):
    c = 0
    while n > 1:
        n //= 2
        c += 1
    return c

def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)
